export function measureBundledText(font: ResumeFontId, weight: 400 | 700, text: string, fontSizePt: number, letterSpacingPt = 0) {
  const face = FACES[font][weight];
  const graphemes = typeof Intl !== "undefined" && "Segmenter" in Intl
    ? [...new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(text)].map(part => part.segment)
    : Array.from(text);
  let units = 0;
  for (const grapheme of graphemes) {
    for (const char of grapheme) units += face.widths[char.codePointAt(0)!] ?? face.fallbackWidth;
  }
  return units * fontSizePt / face.unitsPerEm + Math.max(0, letterSpacingPt) * Math.max(0, graphemes.length - 1);
}
